  "cites": []
}

{
  "decision": "NOTAFF",
  "reason": "The vulnerability affects Apache Directory LDAP API versions 1.2.0 through 1.2.8; bookworm ships version 2.1.2, which is outside the affected range.",
  "cites": ["CVE-2026-35563"]
}

{
  "decision": "URGENT",
  "reason": "The vulnerability allows arbitrary code execution via crafted Kerchunk reference JSON documents in fsspec's ReferenceFileSystem, affecting the version shipped in bookworm (2022.11.0). Since the package is fully supported by LTS and the issue crosses a security boundary (code execution), it warrants an immediate DLA.",
  "cites": []
}

{
  "decision": "NEXT",
  "reason": "The vulnerability is a minor one-byte heap out-of-bounds read in the HTTP stream wrapper when processing an empty Location header; impact is limited to redirect target manipulation and LTS typically batches such low-severity issues for point releases.",
  "cites": ["CVE-2026-17543", "CVE-2026-7260", "CVE-2026-14355"]
}

{
  "decision": "NOTAFF",
  "reason": "CVE-2026-91477 affects Oracle JavaFX 25.0.4 and 27, while bookworm ships OpenJFX 11.0.11; previous Oracle JavaFX CVEs (e.g., CVE-2026-21947, CVE-2024-21005) were marked not-affected for the same reason.",
  "cites": ["CVE-2026-21947", "CVE-2024-21005", "CVE-2024-21004"]
}

{
  "decision": "NEXT",
  "reason": "The vulnerability is a local denial-of-service in iscsiuio's IPv4 DHCP parsing, requiring the attacker to be on the same network segment and the daemon to be actively using DHCP; this is considered a minor issue suitable for batching.",
  "cites": []
}

{
  "decision": "NOTAFF",
  "reason": "The vulnerable fast-uri library is not used in node-ajv version 6.x (bookworm ships 6.12.6-3), which relies on uri-js instead; all recent LTS triages for this package mark fast-uri CVEs as not-affected.",
