}

{
  "decision": "NEXT",
  "reason": "This CVE describes a DoS via excessive memory consumption when processing crafted PDF page labels, which is similar to numerous previous CVEs in pypdf that were all classified as minor issues and postponed for bookworm.",
  "cites": ["CVE-2026-84311", "CVE-2026-84310", "CVE-2026-82398", "CVE-2026-71870", "CVE-2026-59938"]
}

{
  "decision": "NEXT",
  "reason": "Libpng1.6 in bookworm has received both urgent fixes (CVE-2026-22801, CVE-2026-22695) and minor issues deferred via <no-dsa> (CVE-2025-28162); with unknown attack scope, this CVE follows the pattern of batching minor issues.",
  "cites": ["CVE-2025-28162", "CVE-2026-22801"]
}

{
  "decision": "NEXT",
  "reason": "Local denial-of-service via null pointer dereference in m17n-lib is a minor issue; LTS batches such issues for point releases rather than issuing immediate DLAs.",
  "cites": []
}

{
  "decision": "NEXT",
  "reason": "CVE-2026-0965 is a local DoS via configuration file parsing, similar to the other 2026-096x CVEs (CVE-2026-0964, CVE-2026-0966, CVE-2026-0967, CVE-2026-0968) which were all marked <no-dsa> (Minor issue) and deferred for batching.",
